import os
from typing import Any, Dict, List, Optional

import requests


class DatadogMetricsClient:
    def __init__(self, api_key: Optional[str] = None, app_key: Optional[str] = None):
        self.api_key = api_key or os.getenv("DD_API_KEY")
        self.app_key = app_key or os.getenv("DD_APP_KEY")
        if not self.api_key or not self.app_key:
            raise ValueError("DD_API_KEY and DD_APP_KEY must be set")
        self.base_url = os.getenv("DD_SITE", "https://api.datadoghq.com")

    def query_metrics(
        self,
        metric_name: str,
        start_ts: int,
        end_ts: int,
        filter_tags: Optional[List[str]] = None,
        aggregator: str = "avg",
        interval: Optional[int] = None,
    ) -> Dict[str, Any]:
        params: Dict[str, Any] = {
            "from": start_ts,
            "to": end_ts,
            "query": self._build_query(metric_name, filter_tags, aggregator, interval),
        }

        headers = {
            "DD-API-KEY": self.api_key,
            "DD-APPLICATION-KEY": self.app_key,
            "Accept": "application/json",
        }

        resp = requests.get(
            f"{self.base_url}/api/v1/query",
            params=params,
            headers=headers,
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def _build_query(
        metric_name: str,
        filter_tags: Optional[List[str]],
        aggregator: str,
        interval: Optional[int],
    ) -> str:
        tag_clause = ""
        if filter_tags:
            tag_clause = "{" + ",".join(filter_tags) + "}"

        if interval is not None:
            return f"{aggregator}:{metric_name}{tag_clause}.rollup({aggregator}, {interval})"
        return f"{aggregator}:{metric_name}{tag_clause}"


def query_metrics_by_labels(
    metric_name: str,
    start_ts: int,
    end_ts: int,
    labels: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    tags = [f"{k}:{v}" for k, v in (labels or {}).items()]
    client = DatadogMetricsClient()
    return client.query_metrics(metric_name=metric_name, start_ts=start_ts, end_ts=end_ts, filter_tags=tags)
